    startMin: start,
    endMin: end,
    available: true,
    title: coffee ? "\u041A\u043E\u0444\u0435 \u0438 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0439 \u0441\u043E\u043D" : "\u041A\u043E\u0440\u043E\u0442\u043A\u0438\u0439 \u0441\u043E\u043D \u0434\u043D\u0451\u043C",
    detail: coffee ? "\u0411\u044B\u0441\u0442\u0440\u043E \u0432\u044B\u043F\u0435\u0439 \u0447\u0430\u0448\u043A\u0443 \u043A\u043E\u0444\u0435 \u0438 \u0441\u0440\u0430\u0437\u0443 \u043B\u043E\u0436\u0438\u0441\u044C \u043D\u0430 15\u201320 \u043C\u0438\u043D\u0443\u0442. \u041A\u043E\u0444\u0435 \u043F\u043E\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043A\u0430\u043A \u0440\u0430\u0437 \u043A \u043F\u0440\u043E\u0431\u0443\u0436\u0434\u0435\u043D\u0438\u044E \u2014 \u0432\u0441\u0442\u0430\u043D\u0435\u0448\u044C \u0431\u043E\u0434\u0440\u044B\u043C." : "\u041F\u043E\u0441\u043F\u0438 10\u201320 \u043C\u0438\u043D\u0443\u0442, \u043F\u043E\u0441\u0442\u0430\u0432\u044C \u0431\u0443\u0434\u0438\u043B\u044C\u043D\u0438\u043A \u043D\u0430 20. \u0414\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0441\u043F\u0438.",
